local _, WFJ = ...
WFJ.Data.add("book", {
  ["3e17d6d514692320"] = { "Voglio che il capitan Borbotto porti la ⟦The Riptide=Granmarea⟧ a riva da sud-est. Manderemo a terra la sua ciurma a piedi quando verrà dato il segnale.\n\nQuel bestione di Salthoof può guidare gli uomini all'assalto. Voglio la macchia nera per Revilgaz e Seahorn. Mandateli dritti in fondo al mare, per quel che m'importa.\n\nVoi, gaglioffi, dovete recuperare tutto ciò che potrebbe servire al nostro progettino con VanCleef nelle ⟦Deadmines=Miniere della Morte⟧.", "." },
  ["3eac174af3ef44d7"] = { "Caro Zargh,\n\nLe bistecche che mi hai mandato sono perfette. Ben marmorizzate, tagliate spesse e avvolte nel grasso di cinghiale. Proprio come piacciono a me. Quando le mangerò più tardi, penserò a te mentre rosicchio gli ultimi pezzetti di osso e cartilagine. Chiuderò gli occhi e vedrò le tue mani forti e piene di cicatrici che tagliano e affettano...\n\nAh! Mi fa tornare in mente quando hai avuto l'incidente e hai perso un dito... Oh, Zargh! Ripensare a quel giorno mi fa ridacchiare come una ragazzina.\n\nSei così carino quando sanguini!\n\n-Gryshka", "." },
  ["3eaff682e99ead2b"] = { "Oltre al sangue, nella pietra sono fuse forze elementali. Fuoco, acqua, tuono e roccia sono mescolati al sangue (ma, di nuovo, il sangue di cosa?) e, sebbene questa mescolanza all'esterno sia inerte, tutte queste forze sembrano infuriare l'una contro l'altra al suo interno. Sorsero allora molte altre domande su questo materiale straordinario e inquietante.", "." },
  ["3ebc050007c4fc18"] = { "un giorno si sarebbe riunito alla moglie e ai figli.\n\nAlla fine Morgan tornò nella sua terra natale, ma la trovò del tutto diversa da come la ricordava. La foresta, un tempo verdeggiante, era corrotta e brulicava di non morti e di altre forze oscure. Ovunque si vedevano case e fattorie distrutte, e il cimitero vicino a Collecorvo ora dominava gran parte della zona. Sconvolto e smarrito, Morgan raggiunse infine la sua casa, solo per trovarla in rovina. Senza sapere che cosa fosse accaduto alla sua terra,", "." },
  ["3ebcf2e97375acf8"] = { "Riconoscerai un worgen dalla somiglianza con i lupi del nostro mondo. Osservando un worgen si nota facilmente quanto il pelo ispido, le orecchie appuntite e il lungo muso lo accomunino ai lupi che conosciamo.\n\nMa altrettanto in fretta ne vedrai le differenze: quel pelo ispido avvolge un possente corpo bipede, armato di lunghe zanne e di artigli simili a pugnali. E dietro il suo ululato si cela una malvagità che nessuna bestia naturale possiede.", "." },
  ["3ecba93955d07ff7"] = { "Gul'dan accettò e decise che, una volta sconfitti gli abitanti di Azeroth, avrebbe trovato la leggendaria tomba e reclamato la sua ricompensa. Certo che l'⟦Horde=Orda⟧ avrebbe servito i suoi scopi, Sargeras ordinò che l'invasione avesse inizio.", "." },
  ["3ef57344b3f1f5d2"] = { "Lok-tar, fratello o sorella. Gli elementi ti chiamano a sé e mi chiedono di mostrarti la via dello sciamano. Gli spiriti dei nostri antenati osservano dall'aldilà e si gonfiano d'orgoglio sapendo che ora fai parte delle nostre file.\n\nQuando te la senti, cercami vicino all'ingresso dell'Antro del Tirocinio. È lì che addestrerò altri della nostra specie. Fino ad allora, che il vento ti sia alle spalle.\n\n-Shikrik, istruttrice degli sciamani", "." },
})
